// -- Page compositions --

const MockOperatorPage = ({
  isLoading = false,
  showActiveStake = true,
  showClusters = true,
  showInstances = true,
}: {
  isLoading?: boolean;
  showActiveStake?: boolean;
  showClusters?: boolean;
  showInstances?: boolean;
}) => (
  <DarkBackground>
    <OperatorContainer>
      <Flex
        css={{ flexDirection: "column", gap: "$2xl" }}
        data-og-content="true"
      >
        {/* Profile + Operator Instances */}
        <Flex
          css={{
            "@sm": { flexDirection: "column" },
            "@md": { flexDirection: "column" },
            gap: "$xxs",
            justifyContent: "space-between",
          }}
        >
          <Profile
            src="/assets/profile-default.png"
            name="vitalik.eth"
            credential="gold"
            isLoading={isLoading}
            address={MOCK_ADDRESS}
            url={`https://holesky.etherscan.io/address/${MOCK_ADDRESS}`}
          />

          {showInstances && (
            <Flex css={{ width: "auto" }}>
              <Flex css={{ height: "$max" }}>
                <IncentivesSection />
                <VerticalDivider />
                <CredentialSection />
                <VerticalDivider />
                <BadgesSection />
              </Flex>
            </Flex>
          )}
        </Flex>

        {/* Metrics Row */}
        <Flex css={{ gap: "$lg", "@sm": { flexDirection: "column" } }}>
          <MetricWidget
            heading="Clusters"
            content={isLoading ? "" : "6"}
            tooltipContent="The number of clusters that this user operates"
            isLoading={isLoading}
          />
          <MetricWidget
            heading="Validators"
            content={isLoading ? "" : "93"}
            tooltipContent="The number of validators in all of this operators clusters"
            isLoading={isLoading}
          />
          {showActiveStake && (
            <MetricWidget
              css={{ minWidth: "fit-content" }}
              heading="Active Stake"
              content={isLoading ? "" : <ActiveStakeContent />}
              tooltipContent="The total active stake across all of this operator's clusters"
              isLoading={isLoading}
            />
          )}
        </Flex>
      </Flex>

      {/* Cluster List Table */}
      <BoxTable
        css={{
          ".table-container": {
            "@sm": {
              minWidth: "694px",
              width: "fit-content",
              overflowX: "scroll",
            },
          },
        }}
      >
        <TableContainerWithTabs
          isLoading={isLoading}
          tabListCta={<TableClaimCTA />}
          tabs={[
            {
              title: "Clusters",
              count: showClusters ? mockClusterRows.length : 0,
              tableProps: {
                columns: mockColumns,
                rows: showClusters ? mockClusterRows : [],
              },
            },
            {
              title: "Invites",
              count: showClusters ? mockInviteRows.length : 0,
              tableProps: {
                columns: mockColumns,
                rows: showClusters ? mockInviteRows : [],
              },
            },
          ]}
        />
      </BoxTable>
    </OperatorContainer>
  </DarkBackground>
);

